/**
 * Shared field and surface styles for the Base UI variant of Bold retail.
 *
 * These mirror `../components/_shared.ts`, so a Base UI component and its
 * Radix twin render the same field, the same floating panel and the same
 * black controls. Base UI marks state with bare attributes (data-checked,
 * data-highlighted, data-pressed, data-disabled), so the state selectors
 * differ from the Radix file. Import from here instead of re-declaring the
 * classes, or the two variants drift apart.
 */

/** Base styles shared by every form-field surface (Input, Select trigger, etc.) */
export const formFieldBase =
  "w-full min-w-0 rounded-lg border border-(--line-strong) bg-(--field) px-4 text-base text-foreground " +
  "placeholder:text-muted-foreground " +
  "transition-[border-color,box-shadow] duration-fast ease-out " +
  "hover:border-(--control) " +
  "focus-visible:border-foreground focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-(--halo) " +
  "disabled:cursor-not-allowed disabled:bg-secondary disabled:text-(--foreground-disabled) disabled:placeholder:text-(--foreground-disabled) " +
  "data-[disabled]:cursor-not-allowed data-[disabled]:bg-secondary data-[disabled]:text-(--foreground-disabled)";

/** Height + vertical padding for single-line form fields (3rem, the button height) */
export const formFieldSingleLine = "flex h-12 py-3";

/** Vertical padding and min-height for multi-line form fields */
export const formFieldMultiLine = "flex min-h-28 py-3";

/**
 * The soft grey search pill from the store header: filled, borderless, a
 * 1.5rem corner. Focus turns it white with a black edge and the grey halo.
 */
export const searchPill =
  "w-full min-w-0 rounded-3xl border border-transparent bg-secondary px-4 text-base text-foreground " +
  "placeholder:text-muted-foreground transition-[background-color,border-color,box-shadow] duration-fast ease-out " +
  "hover:bg-(--secondary-hover) " +
  "focus-visible:border-foreground focus-visible:bg-background focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-(--halo) " +
  "disabled:cursor-not-allowed disabled:text-(--foreground-disabled)";

/**
 * The floating panel every Base UI menu opens onto: a white panel with a
 * 1rem corner, edged by the hairline ring inside its soft shadow token.
 */
export const popoverSurface =
  "rounded-xl bg-popover text-popover-foreground shadow-(--shadow-menu) outline-none";

/** Popups fade in and settle from their anchor, and leave a little faster. */
export const popupMotion =
  "origin-(--transform-origin) transition-[opacity,scale,translate] duration-fast ease-out " +
  "data-[starting-style]:scale-98 data-[starting-style]:opacity-0 " +
  "data-[ending-style]:scale-98 data-[ending-style]:opacity-0 data-[ending-style]:duration-fast";

/** The popover settles at the system's base duration, both ways. */
export const popoverMotion =
  "origin-(--transform-origin) transition-[opacity,scale,translate] duration-base ease-out " +
  "data-[starting-style]:scale-98 data-[starting-style]:opacity-0 " +
  "data-[ending-style]:scale-98 data-[ending-style]:opacity-0";

/** A highlighted row inside a floating panel: soft grey fill, 0.5rem corner. */
export const menuItemBase =
  "relative flex min-h-9 cursor-default select-none items-center gap-2 rounded-md px-3 py-2 text-sm font-medium outline-none " +
  "transition-colors duration-fast " +
  "data-[highlighted]:bg-accent data-[highlighted]:text-accent-foreground " +
  "data-[disabled]:pointer-events-none data-[disabled]:text-(--foreground-disabled)";

/** The primary fill: flat black. Hover lifts it to charcoal. */
export const primaryFill =
  "bg-primary text-primary-foreground hover:bg-(--primary-hover) active:bg-(--primary-active)";

/** The same flat black on a small checked Base UI control (checkbox, radio, switch). */
export const controlChecked =
  "data-[checked]:border-primary data-[checked]:bg-primary data-[checked]:text-primary-foreground " +
  "data-[disabled]:data-[checked]:border-(--line-strong) data-[disabled]:data-[checked]:bg-muted " +
  "data-[disabled]:data-[checked]:text-(--foreground-disabled)";

/** A pressed Base UI toggle or chip: it flips fully to black with white text. */
export const activeInvert =
  "data-[pressed]:border-primary data-[pressed]:bg-primary data-[pressed]:text-primary-foreground";

/** The focus ring every interactive element uses: a black ring offset from the part. */
export const focusRing =
  "outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background";
